import type { Abi, Address } from "viem";

export interface ChainConfig {
  network: string;
  chainId: number;
  rpcUrl: string | null;
  commerce: { address: Address; abi: Abi };
  router: { address: Address; abi: Abi };
  policy: { address: Address };
  disputeWindowSeconds: number;
  erc20Abi: Abi;
  assets: Array<{ assetId: string; symbol: string; address: Address; decimals: number }>;
}

// Generated by `pnpm chain:export <network>` from the agent's own SDK, so the
// storefront always talks to the exact ERC-8183 contracts the agent signs for.
const chains = import.meta.glob<ChainConfig>("./chain/*.json", { eager: true, import: "default" });

export const NETWORK = (import.meta.env.VITE_NETWORK as string | undefined) ?? "bsc-testnet";
export const AGENT_URL = ((import.meta.env.VITE_AGENT_URL as string | undefined) ?? "http://127.0.0.1:9100").replace(/\/$/, "");
export const WC_PROJECT_ID = (import.meta.env.VITE_WC_PROJECT_ID as string | undefined) ?? "";

const found = chains[`./chain/${NETWORK}.json`];
if (found === undefined) {
  throw new Error(`missing src/chain/${NETWORK}.json — run: pnpm chain:export ${NETWORK}`);
}
export const CHAIN: ChainConfig = found;

export const EXPLORER = CHAIN.chainId === 56 ? "https://bscscan.com" : "https://testnet.bscscan.com";
export const txUrl = (hash: string) => `${EXPLORER}/tx/${hash}`;
export const addressUrl = (addr: string) => `${EXPLORER}/address/${addr}`;

/** Seller's submission window; the job's on-chain expiry adds the dispute window. */
export const SUBMIT_WINDOW_SECONDS = 60 * 60;
